// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address keeper, bool isPausedBefore) public {
        vm.assume(keeper != address(0));
        vm.prank(c.owner());
        c.setKeeper(keeper);

        if (isPausedBefore) {
            vm.prank(keeper);
            c.pauseDeposit();
        }

        bool pausedRef = c.paused();

        assertTrue(isPausedBefore ? pausedRef : true);
    }
}
